INSERT INTO `f_t_measure_method` VALUES ('2344f4bec77203968363534952c581ff', NULL, NULL, '11', '默认方法-20251105124032', '光度测量', '{\"qcParams\": [{\"controlType\": \"平行样重复性\"}], \"energyLamp\": \"\", \"luminosity\": \"1\", \"waveLength\": [\"512\"], \"approxParams\": [{\"resultIdentity\": \"X3\", \"roundingParams\": [{\"id\": \"row_101\", \"lowerLimit\": -5, \"upperLimit\": 100, \"roundingType\": \"1\", \"decimalPlaces\": 3}], \"resultIdentityName\": \"样品的芦荟苷含量\"}], \"responseTime\": \"0.5\", \"resultParams\": [{\"unit\": \"mg/L或mg/kg\", \"resultName\": \"样品的芦荟苷含量\", \"formulaText\": \"X3=(41.67 * A * V5 * V7)/(V6 * V8)\", \"resultIdentity\": \"X3\"}], \"timeInterval\": \"0\", \"luminosityName\": \"Abs\", \"repetitionTime\": \"2\", \"repetitionPattern\": \"不重复\", \"sampleInputParams\": [{\"unit\": \"Abs\", \"paramName\": \"512\", \"resultIdentity\": \"A\"}, {\"unit\": \"mg/L或mg/kg\", \"paramName\": \"所移取的0.5%醋酸镁甲醇溶液的体积(mL)\", \"resultIdentity\": \"V5\"}, {\"unit\": \"mg/L或mg/kg\", \"paramName\": \"用CCl4定容的体积\", \"resultIdentity\": \"V7\"}, {\"unit\": \"mg/L或mg/kg\", \"paramName\": \"所移取的CCl4萃取液的体积(mL)\", \"resultIdentity\": \"V6\"}, {\"unit\": \"mg/L或mg/kg\", \"paramName\": \"移取液体的体积(mL)\", \"resultIdentity\": \"V8\"}], \"spectralBandwidth\": \"2\", \"changeLampWaveLength\": \"361\", \"preProcessParameters\": [\"准确移取一定量的液体样品，或称取一定量的固体样品（精确至0.0001g）加适量热水超声波萃取后，加到盛有60%FeCl3溶液1.0mL,盐酸6mL的150mL回流瓶中混匀，至沸水浴中加热回流4h，放冷，移至150mL分液漏斗中。用1mol/L NaOH溶液4mL和蒸馏水4mL依次洗涤回流瓶，一并倒入分液漏斗中。用CCl4定容至刻度，摇匀。准确吸取一定量的萃取液，置水浴上小心蒸干。准确吸取0.5%醋酸镁甲醇溶液10mL使之溶解。\"], \"referenceStandardName\": \"化妆品用芦荟汁、粉\"}', NULL, '2025-11-05 12:40:33', 'kh-admin', '2025-11-05 12:41:05', NULL, NULL, NULL);
