INSERT INTO `f_t_measure_method` VALUES ('6e5ef8f79458473e069b4a73ede916c0', NULL, NULL, '11', '默认方法-20251106101946', '光度测量', '{\"qcParams\": [{\"controlType\": \"平行样重复性\"}], \"energyLamp\": \"\", \"luminosity\": \"1\", \"waveLength\": [\"550\"], \"approxParams\": [], \"responseTime\": \"0.5\", \"resultParams\": [], \"timeInterval\": \"0\", \"luminosityName\": \"Abs\", \"repetitionTime\": \"2\", \"repetitionPattern\": \"不重复\", \"sampleInputParams\": [{\"unit\": \"Abs\", \"paramName\": \"550\", \"resultIdentity\": \"A\"}], \"spectralBandwidth\": \"2\", \"changeLampWaveLength\": \"361\", \"preProcessParameters\": [\"准确移取一定量的液体样品，或称取一定量的固体样品（精确至0.0001g）加适量热水超声波萃取后，加到盛有60%FeCl3溶液1.0mL,盐酸6mL的150mL回流瓶中混匀，至沸水浴中加热回流4h，放冷，移至150mL分液漏斗中。用1mol/L NaOH溶液4mL和蒸馏水4mL依次洗涤回流瓶，一并倒入分液漏斗中。用CCl4定容至刻度，摇匀。准确吸取一定量的萃取液，置水浴上小心蒸干。准确吸取0.5%醋酸镁甲醇溶液10mL使之溶解。\"], \"referenceStandardName\": \"化妆品用芦荟汁、粉\"}', NULL, '2025-11-06 10:19:47', 'kh-admin', '2025-11-06 11:16:43', NULL, NULL, NULL);
