INSERT INTO `f_t_measure_method` VALUES ('d1fdd1e9ec5f7f1693060e6073746c5e', NULL, NULL, '11', '默认方法-20251105143834', '定量测定', '{\"gain\": 1, \"qcParams\": [], \"curveType\": \"1\", \"energyLamp\": \"0\", \"repeatMode\": \"单池重复\", \"waveLength\": [\"520\"], \"repeatCount\": \"2\", \"approxParams\": [], \"curveFormula\": \"Abs=k1(C)+k0\", \"equationType\": \"f_C\", \"responseTime\": \"0.5\", \"resultParams\": [], \"timeInterval\": \"1\", \"curveTypeName\": \"一次曲线\", \"samplePoolWay\": \"1\", \"energyLampName\": \"钨灯\", \"zeroMethodName\": \"-\", \"coefficientMode\": \"standard\", \"differentialMode\": \"no_differential\", \"equationTypeName\": \"Abs=f(C)\", \"waveLengthParams\": [\"1\"], \"coefficientParams\": [], \"sampleInputParams\": [{\"unit\": \"\", \"paramName\": \"520\", \"resultIdentity\": \"A\"}], \"spectralBandwidth\": \"2\", \"waveLengthFormula\": \"Abs=Abs[520nm]\", \"statisticalContent\": [], \"coefficientModeName\": \"标准曲线法\", \"changeLampWaveLength\": \"361\", \"differentialModeName\": \"不微分\"}', NULL, '2025-11-05 14:38:35', 'kh-admin', '2025-11-05 14:38:35', NULL, NULL, NULL);
INSERT INTO `f_t_measure_method` VALUES ('d48d125fa2189a0df99a070e3c38c33e', NULL, NULL, '11', '默认方法-20251105141424', '光度测量', '{\"qcParams\": [{\"controlType\": \"平行样重复性\"}], \"energyLamp\": \"\", \"luminosity\": \"1\", \"waveLength\": [\"440\"], \"approxParams\": [{\"resultIdentity\": \"X3\", \"roundingParams\": [{\"id\": \"row_101\", \"lowerLimit\": -5, \"upperLimit\": 100, \"roundingType\": \"1\", \"decimalPlaces\": 3}], \"resultIdentityName\": \"样品的芦荟苷含量\"}], \"responseTime\": \"0.5\", \"resultParams\": [{\"unit\": \"mg/L或mg/kg\", \"resultName\": \"样品的芦荟苷含量\", \"formulaText\": \"X3=(41.67 * A * V5 * V7)/(V6 * V8)\", \"resultIdentity\": \"X3\"}], \"timeInterval\": \"0\", \"luminosityName\": \"Abs\", \"repetitionTime\": \"2\", \"repetitionPattern\": \"不重复\", \"sampleInputParams\": [{\"unit\": \"Abs\", \"paramName\": \"440\", \"resultIdentity\": \"A\"}, {\"unit\": \"mg/L或mg/kg\", \"paramName\": \"所移取的0.5%醋酸镁甲醇溶液的体积(mL)\", \"resultIdentity\": \"V5\"}, {\"unit\": \"mg/L或mg/kg\", \"paramName\": \"用CCl4定容的体积\", \"resultIdentity\": \"V7\"}, {\"unit\": \"mg/L或mg/kg\", \"paramName\": \"所移取的CCl4萃取液的体积(mL)\", \"resultIdentity\": \"V6\"}, {\"unit\": \"mg/L或mg/kg\", \"paramName\": \"移取液体的体积(mL)\", \"resultIdentity\": \"V8\"}], \"spectralBandwidth\": \"2\", \"changeLampWaveLength\": \"361\", \"preProcessParameters\": [\"准确移取一定量的液体样品，或称取一定量的固体样品（精确至0.0001g）加适量热水超声波萃取后，加到盛有60%FeCl3溶液1.0mL,盐酸6mL的150mL回流瓶中混匀，至沸水浴中加热回流4h，放冷，移至150mL分液漏斗中。用1mol/L NaOH溶液4mL和蒸馏水4mL依次洗涤回流瓶，一并倒入分液漏斗中。用CCl4定容至刻度，摇匀。准确吸取一定量的萃取液，置水浴上小心蒸干。准确吸取0.5%醋酸镁甲醇溶液10mL使之溶解。\"], \"referenceStandardName\": \"化妆品用芦荟汁、粉\"}', NULL, '2025-11-05 14:14:25', 'kh-admin', '2025-11-05 14:16:50', NULL, NULL, NULL);
INSERT INTO `f_t_measure_method` VALUES ('d968d3364804deb4eae04d907f20dbc1', NULL, NULL, '11', '默认方法-20251104212525', '定量测定', '{\"gain\": 1, \"qcParams\": [], \"curveType\": \"1\", \"energyLamp\": \"0\", \"repeatMode\": \"不重复\", \"waveLength\": [\"660\"], \"repeatCount\": \"\", \"approxParams\": [], \"curveFormula\": \"Abs=k1(C)+k0\", \"equationType\": \"f_C\", \"responseTime\": \"0.5\", \"resultParams\": [], \"timeInterval\": \"\", \"curveTypeName\": \"一次曲线\", \"samplePoolWay\": \"1\", \"energyLampName\": \"钨灯\", \"coefficientMode\": \"standard\", \"differentialMode\": \"no_differential\", \"equationTypeName\": \"Abs=f(C)\", \"waveLengthParams\": [\"1\"], \"coefficientParams\": [], \"sampleInputParams\": [{\"unit\": \"\", \"paramName\": \"660\", \"resultIdentity\": \"A\"}], \"spectralBandwidth\": \"2\", \"waveLengthFormula\": \"Abs=Abs[660nm]\", \"statisticalContent\": [], \"coefficientModeName\": \"标准曲线法\", \"changeLampWaveLength\": \"361\", \"differentialModeName\": \"不微分\"}', NULL, '2025-11-04 21:25:26', 'admin', '2025-11-04 21:25:26', NULL, NULL, NULL);
