INSERT INTO `f_t_measure_method` VALUES ('f5d2923dd29896d891c69a8fa2f9f16b', NULL, NULL, '11', '默认方法-20251105123055', '光度测量', '{\"qcParams\": [], \"energyLamp\": \"\", \"luminosity\": \"1\", \"waveLength\": [\"250\"], \"approxParams\": [{\"resultIdentity\": \"X3\", \"roundingParams\": [{\"id\": \"row_81\", \"lowerLimit\": -10, \"roundingType\": \"1\", \"decimalPlaces\": 3}], \"resultIdentityName\": \"呈味核苷酸二钠含量\"}], \"responseTime\": \"0.5\", \"resultParams\": [{\"unit\": \"g/100g\", \"resultName\": \"呈味核苷酸二钠含量\", \"formulaText\": \"X3=(A*530*2000)/(m3*11950*1000)*100\", \"resultIdentity\": \"X3\"}], \"timeInterval\": \"0\", \"luminosityName\": \"Abs\", \"repetitionTime\": \"2\", \"repetitionPattern\": \"不重复\", \"sampleInputParams\": [{\"unit\": \"Abs\", \"paramName\": \"250\", \"resultIdentity\": \"A\"}, {\"unit\": \"g/100g\", \"paramName\": \"试样溶液在250nm 处测得的吸光度;\", \"resultIdentity\": \"A\"}], \"spectralBandwidth\": \"2\", \"changeLampWaveLength\": \"361\", \"preProcessParameters\": [\"分析步骤\\n准确称取均匀的样品 2g~4g，用少量 0.01mol/L 的盐酸溶液溶解，定容于 100mL 的容量瓶中，混匀，过滤，弃去初滤液，吸取滤液 5.00mL 于 100mL 的容量瓶，用 0.01mol/L 的盐酸溶液定容，混匀，此溶液即为测试液。\\n将测试液注入10mm的石英比色皿中，以0.01mol/L的盐酸溶液作空白，测其在波长250nm下的吸光度。\"], \"referenceStandardName\": \"鸡精调味料\"}', NULL, '2025-11-05 12:30:56', 'kh-admin', '2025-11-05 12:30:56', NULL, NULL, NULL);
INSERT INTO `f_t_measure_method` VALUES ('fbf4942c3498a83509a9290a2efe6809', NULL, NULL, NULL, '时间扫描OWrEq9o7', '时间扫描', '{\"gain\": 3, \"scanTime\": \"30\", \"scanUnit\": \"1\", \"energyLamp\": \"1\", \"luminosity\": \"1\", \"waveLength\": \"560\", \"totalNumber\": \"21\", \"intervalTime\": \"1.5\", \"responseTime\": \"0.5\", \"multiPoolMode\": \"0\", \"energyLampName\": \"氘灯\", \"spectralBandwidth\": \"2\", \"changeLampWaveLength\": \"361\"}', NULL, '2025-11-06 11:32:09', 'kh-admin', '2025-11-06 11:32:09', NULL, NULL, NULL);
